 const engineDraft=E.process(q);const citizenMatch=U&&!safe.sensitive?U.match(safe.query):null;if(citizenMatch?.services.length===1&&engineDraft.results.length<=1&&['portal','app','engine','needs-provider'].includes(citizenMatch.services[0].kind)){selectedService=citizenMatch.services[0].id;serviceEvidence=window.VN_EVIDENCE.classify(safe.query,norm).requiresUpdatedEvidence;page='citizen';render();return;}
