document.addEventListener('change',async event=>{const node=event.target;if(node.id==='appImport'){const file=node.files?.[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Tệp danh mục tối đa 20 MB.');const items=C.parseBackup(await file.text());if(!window.confirm('Khôi phục '+items.length+' app? Mục trùng liên kết sẽ được cập nhật.'))return;await customRepo.import(items);customApps=await customRepo.list();catalogMessage='Đã khôi phục danh mục app.';render();}catch(e){setStatus(e.message);}finally{node.value='';}return;}if(node.dataset&&node.dataset.checkService&&U){const id=node.dataset.checkService,index=Number(node.dataset.checkIndex);if(!U.SERVICES.some(x=>x.id===id)||!Number.isInteger(index)||index<0||index>=U.checklist(id).length)return;const chosen=checks.get(id)||new Set();node.checked?chosen.add(index):chosen.delete(index);checks.set(id,chosen);const summary=node.closest?.('details')?.querySelector?.('summary');if(summary)summary.textContent='Danh sách tự kiểm tra · '+chosen.size+'/'+U.checklist(id).length;setStatus('Đã đổi dấu tự kiểm tra. Chưa xác nhận kết quả tại dịch vụ đích.');return;}if(!W)return;const id=event.target.id;if(!['waterRegion','waterArea','waterProvider','waterConfirmed','waterRural'].includes(id))return;const draft=$('waterSearchForm')?.elements?.query;if(draft)waterQuery=draft.value;if(id==='waterRegion'){waterRegion=event.target.value;waterArea='';waterProvider='';waterConfirmed=false;waterLimit=3;}if(id==='waterArea'){waterArea=event.target.value;waterProvider='';waterConfirmed=false;}if(id==='waterRural'){waterNeed.rural=event.target.checked===true;waterProvider='';waterConfirmed=false;waterLimit=3;}if(id==='waterProvider'){waterProvider=event.target.value;waterConfirmed=false;}if(id==='waterConfirmed')waterConfirmed=event.target.checked===true;$('routeBody').innerHTML=page==='water'?waterPanel():page==='citizen'?citizenDetail():billingView(billingTypes);const focus=$(id);if(focus&&focus.focus)focus.focus();});
